import Dispatch
final class ChargeStats {
    private let queue = DispatchQueue(label: "charge.stats")
    private var completed = 0
    private var failed = 0
    func finishFailure() -> (Int, Int) {
        queue.sync {
            completed += 1
            failed += 1
            return (completed, failed)
        }
    }
    func snapshot() -> (Int, Int) { queue.sync { (completed, failed) } }
}
let stats = ChargeStats()
print(stats.finishFailure())
print(stats.snapshot())

До правки (1, 0), (1, 1); после — (1, 1), (1, 1). Изменение пары и её чтение получили цельные границы; промежуточный снимок в модели больше не создаётся.

