import Dispatch
final class RecipeIDs {
    private let queue = DispatchQueue(label: "recipes.ids")
    private var next = 10
    func nextID() -> Int {
        queue.sync {
            let result = next
            next += 1
            return result
        }
    }
}
let source = RecipeIDs()
print(source.nextID())
print(source.nextID())

Вывод 10, 11. Выдача уникального номера — одна read-modify-write-операция, не отдельный read плюс setter.

