import Dispatch
final class RouteStops {
    private let queue = DispatchQueue(label: "route.stops")
    private var rows: [String] = []
    func add(_ title: String) { queue.sync { rows.append(title) } }
    func snapshot() -> [String] { queue.sync { rows } }
}
let stops = RouteStops()
stops.add("Мост")
var copy = stops.snapshot()
copy.append("Парк")
print(copy.count)
print(stops.snapshot().count)

Вывод 2, 1. Наружу возвращено значение со String-элементами, а не общий изменяемый объект. Для массива элементов-классов потребовался бы отдельный контракт их изменения.
